      console.log('🔍 Inlining same-origin and srcDoc iframes recursively...');
      await page.evaluate(() => {
        const inlineSameOriginIframes = (root: Document | HTMLElement) => {
          const iframes = Array.from(root.querySelectorAll('iframe'));
