    // -----------------------------------------------------------------------
    console.log('🖼️  Inlining images as base64...');
    stats.images = await page.evaluate(async () => {
      const { toDataUri, processInBatches, CONCURRENCY } = (window as any).__snapshot;
      let count = 0;

