          const [url, ...descriptors] = part.split(/\s+/);
          if (url.startsWith('data:')) {
            newParts.push(part);
            return;
          }
          const dataUri = await toDataUri(url);
          if (dataUri) {
            newParts.push([dataUri, ...descriptors].join(' '));
            count++;
          }
